  /** Chart canvas와 custom legend만 PNG로 내보내는 imperative handle ref */
  exportRef?: Ref<ChartFrameExportHandle>;
  interactionLayer?: false | ChartInteractionLayerOptions;
  legend?: false | ChartLegendOptions;
  /** 동일 group의 chart pointer와 zoom 동기화 */
  linkedInteraction?: false | ChartLinkedInteractionOptions;
  /** Chart plot 영역 loading overlay 표시 여부 */
  loading?: boolean;
  /** 빈 데이터 표시는 호출자가 제어한다. 기본값 false이며 null·0·숨김 상태로 자동 판정하지 않는다. */
  noData?: boolean;
  /** noData=true일 때 표시할 문구. 기본값: “조회 결과가 없습니다.” (i18n 적용) */
  noDataMessage?: string;
  /** 오류 안내와 재시도 action. 우선순위는 loading → errorOverlay → noData다. */
  errorOverlay?: false | ChartErrorOverlayOptions;
  /** Chart 상단 오른쪽 PNG 다운로드 버튼 표시 여부 */
  showExportButton?: boolean;
  /** Chart.js title plugin에 표시할 chart title */
  title?: string;
  /** x축 label 기준점에 표시하는 짧은 marker */
  xAxisLabelMarker?: false | ChartAxisLabelMarkerOptions;
  zoomSlider?: false | ChartZoomSliderOptions;
};

