interface OwpDataGridApi<T extends OwpDataGridRow = OwpDataGridRow> {
  /** 현재 draft를 즉시 working row에 확정. editor가 없으면 true. 저장 전 validate 별도 실행 */
  commitEditing: () => boolean;
  /**
   * 편집 중이면 실패. 모든 operation을 staging한 뒤 반영, onChangesChange 한 번 호출.
   * 성공 이후 onCellValueCommit을 operation 순서로 전달. setter/validator 예외는 callback-error.
   * 성공 알림 callback 예외는 호출부로 전파하며 이미 반영한 model을 rollback하지 않음.
   */
  applyTransaction: (operations: readonly OwpDataGridTransactionOperation<T>[]) => OwpDataGridCommandResult;
  /**
   * 저장된 전체 row로 baseline 갱신, 요청 이후 수정 보존. 편집 중이면 실패.
   * 전달된 row만 반영하고 onChangesChange 한 번 호출. 서버 응답 순서/버전 검사는 호출부 책임.
   */
  applyServerRows: (options: OwpDataGridServerRowsOptions<T>) => OwpDataGridCommandResult;
  /**
   * rowIds에 포함된 row의 현재 값과 순서를 새 baseline으로 확정. default: loaded row 전체, []: no-op.
   * 삭제 승인은 loaded subtree 전체 ID 필요. 요청 중 추가 수정이 가능하면 applyServerRows 사용.
   * 편집 중이면 실패. HTTP 저장은 호출부 책임.
   */
