interface EllipseAnnotationOptions extends CoreAnnotationOptions {
  backgroundColor?: Scriptable<Color, PartialEventContext>,
  label?: BoxLabelOptions,
  rotation?: Scriptable<number, PartialEventContext>
}

interface LabelAnnotationOptions extends CoreAnnotationOptions, LabelTypeOptions, AnnotationPointCoordinates {
