interface LabelPositionObject {
  x?: LabelPosition,
  y?: LabelPosition
}

interface LabelTypeOptions extends ContainedLabelOptions {
  position?: Scriptable<LabelPosition | LabelPositionObject, PartialEventContext>,
  z?: Scriptable<number, PartialEventContext>,
  callout?: CalloutOptions,
}

interface Context {
  /**
   * Whether the associated element is hovered by the user.
   * @see https://www.chartjs.org/docs/latest/configuration/interactions.html
   * @since 0.3.0
   */
  active: boolean;

  /**
   * The associated chart.
   * @since 0.1.0
   */
  chart: Chart;

  /**
   * Index of the current data.
   * @since 0.1.0
   */
  dataIndex: number;

  /**
   * The current dataset at index `datasetIndex`.
   * @since 0.1.0
   */
  dataset: ChartDataset;

  /**
   * Index of the current dataset.
   * @since 0.1.0
   */
  datasetIndex: number;
}

